export function faceName(id: number): string {
  const marker = Math.floor(id / 8) % 8;
  return `${COLORS[marker]} ${id < 64 ? 'solid' : 'outline'} ${SHAPES[id % 8]}, marker ${MARKERS[marker]}`;
}

